 * lead, and not an explicit project member. Callers already know an admin,
 * owner or platform-staff actor sees everything, so they skip this query
 * entirely rather than passing it a role that always resolves empty.
 */
export async function listHiddenPrivateProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        eq(projects.visibility, "private"),
        or(isNull(projects.leadId), ne(projects.leadId, userId)),
        notExists(
          getDb()
