/**
 * The private-visibility rule: a `private` project (and everything under it)
 * is visible only to an admin/owner, platform staff, the project's lead, or
 * an explicit project member. `org` and `public` projects are visible to
 * anyone already scoped to the org.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(project.orgId, project.id, actor.userId);
}

/** Throws `NotFoundError` under `id` when `project` must behave as absent. */
async function assertProjectVisible(
  actor: Actor,
  project: Project,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", id);
  }
}

/**
 * Ids of private projects the actor cannot see, for filtering listings. An
 * admin, owner or platform-staff actor sees every private project, so the
 * membership query is skipped entirely for them.
 */
export async function hiddenPrivateProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true) return [];
  if (hasRoleAtLeast(actor.role, "admin")) return [];
  return projectRepo.listHiddenPrivateProjectIds(orgId, actor.userId);
}

