36	 * is visible only to an admin/owner, platform staff, the project's lead, or
37	 * an explicit project member. `org` and `public` projects are visible to
38	 * anyone already scoped to the org.
39	 */
40	export async function canViewProject(
41	  actor: Actor,
42	  project: Project,
43	): Promise<boolean> {
44	  if (project.visibility !== "private") return true;
45	  if (actor.orgId !== project.orgId) return false;
46	  if (actor.isPlatformStaff === true) return true;
47	  if (hasRoleAtLeast(actor.role, "admin")) return true;
48	  if (project.leadId === actor.userId) return true;
