import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function privateProjectInput(orgId: OrgId, leadId: string | null): CreateProjectInput {
  return {
    orgId,
    name: "Secret Project",
    slug: "secret",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: leadId as never,
    color: "#000000",
    targetDate: null,
  };
}

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("private project visibility sanity", () => {
  it("hides a private project from a non-member/non-lead member, but shows it to admin/owner/member-added", async () => {
    const tenant = await createTenant("privsanity", "growth");

    const secret = await projectService.createProject(
      tenant.actors.admin,
      privateProjectInput(tenant.org.id, tenant.userIds.owner),
    );

    // Not lead, not admin/owner, not a project member -> NotFoundError
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, secret.slug),
    ).rejects.toBeInstanceOf(NotFoundError);

    // admin/owner sees it regardless
    await expect(
      projectService.getProject(tenant.actors.admin, tenant.org.id, secret.slug),
    ).resolves.toBeDefined();

    // lead sees it
    await expect(
      projectService.getProject(tenant.actors.owner, tenant.org.id, secret.slug),
    ).resolves.toBeDefined();

    // add member as project member -> now visible
    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, tenant.userIds.member);
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, secret.slug),
    ).resolves.toBeDefined();

    // listProjects excludes it (and total reflects that) for a non-member viewer
    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, tenant.userIds.member);
    const page = await projectService.listProjects(tenant.actors.viewer, {
      orgId: tenant.org.id,
      cursor: null,
      limit: 20,
    });
    expect(page.items.some((p) => p.project.id === secret.id)).toBe(false);

    const adminPage = await projectService.listProjects(tenant.actors.admin, {
      orgId: tenant.org.id,
      cursor: null,
      limit: 20,
    });
    expect(adminPage.items.some((p) => p.project.id === secret.id)).toBe(true);
    expect(adminPage.total).toBe(page.total + 1);

    // Issue under the hidden project: creation, read, update all 404 for viewer
    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, secret.id, { title: "Hidden issue" }),
    );

    await expect(
      issueService.getIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, secret.id, { title: "should 404" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    // org-wide issue list excludes it
    const issuesPage = await issueService.listIssues(tenant.actors.viewer, {
      orgId: tenant.org.id,
      cursor: null,
      limit: 20,
    });
    expect(issuesPage.items.some((i) => i.id === issue.id)).toBe(false);

    // comment thread 404s for viewer, works for admin
    await expect(
      commentService.getThread(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.getThread(tenant.actors.admin, tenant.org.id, issue.id),
    ).resolves.toBeDefined();

    // Sanity: a non-private (org) project's issue still throws PermissionDeniedError, not NotFoundError, for real permission failures
    await expect(
      projectService.archiveProject(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: false,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

